import warnings as _dw_warnings

def _dw_wrap_proxies(_cls, _transport_cls):
    _orig_init = _cls.__init__

    def __init__(self, *args, proxies=None, **kwargs):
        if proxies is not None:
            _dw_warnings.warn(
                "The 'proxies' argument is deprecated; use 'proxy' or 'mounts' instead.",
                DeprecationWarning,
                stacklevel=2,
            )
            if isinstance(proxies, (str, URL, Proxy)):
                if kwargs.get("proxy") is None:
                    kwargs["proxy"] = proxies
            else:
                mounts = dict(kwargs.pop("mounts", None) or {})
                for _key, _value in proxies.items():
                    if _key in mounts:
                        continue
                    if _value is None:
                        mounts[_key] = None
                    else:
                        mounts[_key] = _transport_cls(
                            verify=kwargs.get("verify", True),
                            cert=kwargs.get("cert"),
                            http1=kwargs.get("http1", True),
                            http2=kwargs.get("http2", False),
                            limits=kwargs.get("limits", DEFAULT_LIMITS),
                            trust_env=kwargs.get("trust_env", True),
                            proxy=_value,
                        )
                kwargs["mounts"] = mounts
        _orig_init(self, *args, **kwargs)

    __init__.__wrapped__ = _orig_init
    _cls.__init__ = __init__

from ._config import DEFAULT_LIMITS
_dw_wrap_proxies(Client, HTTPTransport)
_dw_wrap_proxies(AsyncClient, AsyncHTTPTransport)
